import contextlib
import io
import unittest

from textkit import roman
from textkit.cli import main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class ToRomanTest(unittest.TestCase):
    def test_known_values(self):
        self.assertEqual(roman.to_roman(1), "I")
        self.assertEqual(roman.to_roman(4), "IV")
        self.assertEqual(roman.to_roman(1994), "MCMXCIV")
        self.assertEqual(roman.to_roman(3999), "MMMCMXCIX")

    def test_out_of_range_raises(self):
        for n in (0, -1, 4000):
            with self.subTest(n=n), self.assertRaises(ValueError):
                roman.to_roman(n)

    def test_non_int_raises(self):
        for n in ("5", 2.0, None):
            with self.subTest(n=n), self.assertRaises(ValueError):
                roman.to_roman(n)


class FromRomanTest(unittest.TestCase):
    def test_known_values(self):
        self.assertEqual(roman.from_roman("I"), 1)
        self.assertEqual(roman.from_roman("MCMXCIV"), 1994)
        self.assertEqual(roman.from_roman("MMMCMXCIX"), 3999)

    def test_non_canonical_raises(self):
        for s in ("IIII", "IC", "VX", "mcm", "", "IM", "VV", "XLX", "ABC", "IVI"):
            with self.subTest(s=s), self.assertRaises(ValueError):
                roman.from_roman(s)

    def test_non_string_raises(self):
        with self.assertRaises(ValueError):
            roman.from_roman(None)


class RoundTripTest(unittest.TestCase):
    def test_round_trip_every_value(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                self.assertEqual(roman.from_roman(roman.to_roman(n)), n)


class RomanCommandTest(unittest.TestCase):
    def test_number_to_numeral(self):
        self.assertEqual(run("roman", "1994"), (0, "MCMXCIV\n", ""))

    def test_numeral_to_number(self):
        self.assertEqual(run("roman", "MCMXCIV"), (0, "1994\n", ""))

    def test_out_of_range_exits_2(self):
        for value in ("0", "4000"):
            with self.subTest(value=value):
                code, out, err = run("roman", value)
                self.assertEqual(code, 2)
                self.assertEqual(out, "")
                self.assertTrue(err.startswith("error:"))

    def test_non_canonical_exits_2(self):
        for value in ("IIII", "IC", ""):
            with self.subTest(value=value):
                code, out, err = run("roman", value)
                self.assertEqual(code, 2)
                self.assertEqual(out, "")
                self.assertTrue(err.startswith("error:"))


if __name__ == "__main__":
    unittest.main()

